import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= 32) {
                b = readByte();
            }
            int n = 0;
            while (isPrintableChar(b)) {
                if (b >= '0' && b <= '9') {
                    n = n * 10 + (b - '0');
                }
                b = readByte();
            }
            return n;
        }
    }

    static class Tree {
        int n;
        int[] head;
        int[] next;
        int[] to;
        int edgeCount;

        Tree(int n) {
            this.n = n;
            head = new int[n + 1];
            Arrays.fill(head, -1);
            next = new int[2 * (n - 1)];
            to = new int[2 * (n - 1)];
            edgeCount = 0;
        }

        void addEdge(int u, int v) {
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        int findCenter() {
            int[] dist = new int[n + 1];
            int[] parent = new int[n + 1];
            int[] queue = new int[n + 1];

            // 1st BFS from node 1
            int u = bfs(1, dist, parent, queue);

            // 2nd BFS from u to find diameter path to v
            int v = bfs(u, dist, parent, queue);

            // Reconstruct diameter path from v back to u
            int pathLength = dist[v];
            int curr = v;
            for (int i = 0; i < pathLength / 2; i++) {
                curr = parent[curr];
            }
            return curr;
        }

        private int bfs(int start, int[] dist, int[] parent, int[] queue) {
            Arrays.fill(dist, -1);
            int headQ = 0, tailQ = 0;

            dist[start] = 0;
            parent[start] = -1;
            queue[tailQ++] = start;

            int farthestNode = start;

            while (headQ < tailQ) {
                int curr = queue[headQ++];

                if (dist[curr] > dist[farthestNode]) {
                    farthestNode = curr;
                }

                for (int e = head[curr]; e != -1; e = next[e]) {
                    int neighbor = to[e];
                    if (dist[neighbor] == -1) {
                        dist[neighbor] = dist[curr] + 1;
                        parent[neighbor] = curr;
                        queue[tailQ++] = neighbor;
                    }
                }
            }

            return farthestNode;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        Tree tree1 = new Tree(n);
        for (int i = 0; i < n - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            tree1.addEdge(u, v);
        }

        Tree tree2 = new Tree(m);
        for (int i = 0; i < m - 1; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            tree2.addEdge(u, v);
        }

        int center1 = tree1.findCenter();
        int center2 = tree2.findCenter();

        System.out.println(center1 + " " + center2);
    }
}
